import torch.nn as nn
import torch
import torch.nn.functional as F
from torch.autograd import Variable
import copy
import numpy as np
from .config import DEVICE
import math


def cosine_anneling(t, k):
    return 0.5 * (1 + math.cos(t * math.pi / k))
def linear(t, k):
    return 1 - k*t
def exp_decay(t, k):
    return (t + 1)**(-k)

# Given stable units, find the plastic units
def compute_plastic(model, stable_indices):
    weight = list_of_weights(model)
    units = [w[1].shape[0] for w in weight]
    plastic_indices = []
    for i,  b_layer in enumerate(stable_indices[1:]):
        all_units = set(range(units[i]))
        plastic_units = all_units.difference(set(b_layer))
        plastic_indices.append(list(plastic_units))
    return [[]] + plastic_indices

#Get sparse connecivity masks
def  get_masks(model):
    l = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, torch.nn.Conv2d) :
            weight_mask, _ = module.get_mask()
            l.append(weight_mask)
    return l

#Find stable untis and drop connections
def compute_stable_and_drop_connections(pruned_model, in_channels, stable_units_set, train_loader, current_classes, classes_so_far, stable_activation_perc, model_type):
    stable_units_set = copy.deepcopy(stable_units_set)
    pruned_model = copy.deepcopy(pruned_model)
    activation_before_drop, _ = compute_average_activation(pruned_model, train_loader,
                                                            DEVICE, current_classes, False)

    stable_indices_new = compute_stable_neurons(activation_before_drop,  in_channels, classes_so_far, activation_perc = stable_activation_perc, model_type = model_type)

    if len(stable_units_set) == 0:
        stable_units_set = [set(stable_index) for stable_index in stable_indices_new]
        stable_indices =  [list(stable_set) for stable_set in stable_units_set]
    else:
        stable_units_set = [prev_set.union(set(stable_index)) for stable_index, prev_set in zip(stable_indices_new, stable_units_set)]
        stable_indices =  [list(stable_set) for stable_set in stable_units_set]


    stable_indices_new = fix_dead_stable_units(stable_indices_new, pruned_model)

    freeze_masks_new, drop_masks = compute_freeze_and_drop(stable_indices, pruned_model)
    pruned_model, num_dropped_connections  = drop_connections(pruned_model, drop_masks, DEVICE)

    return pruned_model, freeze_masks_new, num_dropped_connections, stable_indices, stable_units_set

#Find the percentage of frozen connections
def connection_freeze_perc(freeze_masks, prune_perc):
    layers = []
    for freeze_mask in freeze_masks:
        a = freeze_mask[0].shape
        total_connections = int(np.prod(a)*(1 - prune_perc / 100))
        frozen_connections =  np.sum(freeze_mask[0])
        layers.append(100*(frozen_connections / total_connections))
    return layers


#Fix dead plastic units
def fix_no_outgoing(model, plastic_indices, num_dropped_connections):
    weight = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, torch.nn.Conv2d):
            weight_mask, bias_mask = module.get_mask()
            weight.append((copy.deepcopy(weight_mask).cpu().numpy(), copy.deepcopy(bias_mask).cpu().numpy()))

    new_masks = [weight[0][0]]
    bias_masks = [weight[0][1]]
    for i, layer_indices in enumerate(plastic_indices[1:-1], start = 1):
        M = weight[i][0]
        kernel_size = (M.shape[2] * M.shape[3]) if len(M.shape) == 4 else 1
        for unit_index in layer_indices:
            #not enough connections to fix all
            if num_dropped_connections[i] == 0 or len(plastic_indices[i + 1]) == 0:
                continue
            #Dead unit
            if np.sum(np.abs(M[:, unit_index])) == 0:
                target = np.random.choice(plastic_indices[i + 1], 1)
                M[target, unit_index] = np.ones((M.shape[2], M.shape[3])) if len(M.shape) == 4 else 1
                num_dropped_connections[i] =  num_dropped_connections[i] - kernel_size
        new_masks.append(M)
        bias_masks.append(weight[i][1])
    new_masks.append(weight[-1][0])
    bias_masks.append(weight[-1][1])
    model.set_masks(new_masks, bias_masks)
    return model, num_dropped_connections


#Degrade dead stable units to plastic
def fix_dead_stable_units(stable_indices,  model):
    weight = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, torch.nn.Conv2d):
            weight_mask, bias_mask = module.get_mask()
            weight.append((copy.deepcopy(weight_mask).cpu().numpy(), copy.deepcopy(bias_mask).cpu().numpy()))

    new_stable_units = [stable_indices[0]]
    for i, (source_stable, target_stable) in enumerate(zip(stable_indices[:-1], stable_indices[1:])):
        source_stable, target_stable = np.array(source_stable, dtype=np.int32), np.array(target_stable, dtype=np.int32)
        dead_stable_units = []
        for tgt in target_stable:
            if np.sum(np.abs(weight[i][0][tgt, source_stable])) == 0:
                dead_stable_units.append(tgt)
        if len(dead_stable_units) != 0:
            updated_stable_indices = list(target_stable)
            for dead_stable in dead_stable_units:
                updated_stable_indices.remove(dead_stable)
            new_stable_units.append(updated_stable_indices)
        else:
            new_stable_units.append(list(target_stable))
    return new_stable_units

#Get list of weights
def list_of_weights(network):
    weights = []
    for module in network.modules():
        if isinstance(module, nn.Linear) or isinstance(module, nn.Conv2d):
            weights.append((module.weight.cpu().detach().numpy(), module.bias.cpu().detach().numpy()))
    return weights

#Compute total activation of layers
def compute_total_activation(network, train_loader, dev, current_classes = None, binary = False):
    total_activations = []
    network.train()
    with torch.no_grad():
        for batch_idx, (data, target, _) in enumerate(train_loader):
            _, activations = network.forward_activations(data, current_classes)
            batch_sum_activation = [torch.sum(activation, axis = (0, 2, 3)) if len(activation.shape) != 2 else  torch.sum(activation, axis = 0) for activation in activations]

            if len(total_activations) == 0:
                total_activations = batch_sum_activation
            else:
                total_activations = [total_activations[i]+activation for i, activation in enumerate(batch_sum_activation)]

    return [total_activation.detach().cpu().numpy() for total_activation in total_activations], list_of_weights(network)

#Compute total average activation of layers (this is effectively same with above, only difference is normalization)
def compute_average_activation(network, train_loader, dev, current_classes = None, binary = False):
    total_activations = []
    network.train()
    with torch.no_grad():
        for batch_idx, (data, target, _) in enumerate(train_loader):
            _, activations = network.forward_activations(data, current_classes)
            batch_sum_activation = [torch.sum(activation, axis = (0, 2, 3)) if len(activation.shape) != 2 else  torch.sum(activation, axis = 0) for activation in activations]

            if len(total_activations) == 0:
                total_activations = batch_sum_activation
            else:
                total_activations = [total_activations[i]+activation for i, activation in enumerate(batch_sum_activation)]

    average_activations = [total_activation/len(train_loader.dataset) for total_activation in total_activations]
    return [average_activation.detach().cpu().numpy() for average_activation in average_activations], list_of_weights(network)

# Pick most active units 
def pick_top_neurons(activations, percentage):
    total = sum(activations)
    accumulate = 0
    indices = []
    sort_indices = np.argsort(-activations)
    for index in sort_indices:
       accumulate += activations[index]
       indices.append(index)
       if accumulate >= total * percentage / 100:
           break
    return indices

#Find the stable units that satisfies p criterion
def compute_stable_neurons(activations, in_channels, stable_outputs, activation_perc, model_type):
    stable_indices = []

    for layer_activation in activations[0 if model_type == "conv" or model_type == "conv2"  else 1:-1]:
        stable_indices.append(pick_top_neurons(layer_activation, activation_perc))
    return [list(range(in_channels))] + stable_indices + [stable_outputs]

#Compute which connections to freeze and drop
def compute_freeze_and_drop(stable_indices, model):
    weight = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, nn.Conv2d):
            weight_mask, bias_mask = module.get_mask()
            weight.append((copy.deepcopy(weight_mask).cpu().numpy(), copy.deepcopy(bias_mask).cpu().numpy()))

    #Create Freeze Masks        
    freeze_masks = []
    for i, (source_stable, target_stable) in enumerate(zip(stable_indices[:-1], stable_indices[1:])):
        source_stable, target_stable = np.array(source_stable, dtype=np.int32), np.array(target_stable, dtype=np.int32)
        mask_w = np.zeros(weight[i][0].shape)
        #Conv2Conv
        if len(weight[i][0].shape) == 4:
            for src_unit_stable in source_stable:
               mask_w[target_stable, src_unit_stable, :, :] = np.ones((weight[i][0].shape[2], weight[i][0].shape[3]))
        #Conv2Linear or Linear2Linear
        else:
            #Conv2Linear
            if len(weight[i-1][0].shape) == 4:
                for src_unit_stable in source_stable:

                    mask_w[target_stable, src_unit_stable*model.conv2lin_kernel_size:(src_unit_stable + 1)*model.conv2lin_kernel_size] = 1 
            #Linear2Linear
            else:
                for src_unit_stable in source_stable:
                    mask_w[target_stable, src_unit_stable] = 1 
        mask_b = np.zeros(weight[i][1].shape)
        mask_b[target_stable] = 1
        freeze_masks.append((mask_w, mask_b))

    #Create Drop Masks
    drop_masks = []
    for i, (mask_w, mask_b) in enumerate(freeze_masks):
        mask_w_drop = np.zeros(weight[i][0].shape)
        #Conv2Conv
        if len(weight[i][0].shape) == 4:
            for unit_index, b in enumerate(mask_b):
                if b:
                    mask_w_drop[unit_index, :, :, :] = np.logical_not(mask_w[unit_index])

        #Conv2Linear or Linear2Linear
        else:
            mask_w_drop = np.zeros(weight[i][0].shape)
            for unit_index, b in enumerate(mask_b):
                if b:
                    mask_w_drop[unit_index, :] = np.logical_not(mask_w[unit_index, :])
        drop_masks.append((mask_w_drop, []))
    return freeze_masks, drop_masks

# Calculate the sparsity of the model
def compute_weight_sparsity(model):
    parameters = 0
    ones = 0
    for module in model.modules():
        if isinstance(module, nn.Linear) or isinstance(module, nn.Conv2d):
            shape = module.weight.data.shape
            parameters += torch.prod(torch.tensor(shape))
            w_mask, _ = copy.deepcopy(module.get_mask())
            ones += torch.count_nonzero(w_mask)
    return float((parameters - ones) / parameters) * 100

# Drop connections plastic -> stable
def drop_connections(model, drop_masks, device):
    #Drop connections
    mask_index = 0
    num_drops = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, nn.Conv2d):
            weight_mask, bias_mask = module.get_mask()
            before = torch.sum(weight_mask)
            weight_mask[torch.tensor(drop_masks[mask_index][0], dtype= bool)] = 0 
            after = torch.sum(weight_mask)
            num_drops.append(int(before - after))
            module.set_mask(weight_mask, bias_mask)
            mask_index += 1
    return model, num_drops


class MaskedLinearDynamic(nn.Linear):
    def __init__(self, in_features, out_features, bias=True):
        super(MaskedLinearDynamic, self).__init__(in_features, out_features, bias)
        self.mask_flag = False
        self.bias_flag = bias
        self.sparse_grads = True

    def set_mask(self, weight_mask, bias_mask):
        self.weight_mask = to_var(weight_mask, requires_grad=False)
        self.weight.data = self.weight.data * self.weight_mask.data
        if self.bias_flag == True:
            self.bias_mask = to_var(bias_mask, requires_grad=False)
            self.bias.data = self.bias.data * self.bias_mask.data
        self.mask_flag = True

    def get_mask(self):
        return self.weight_mask, self.bias_mask

    def forward(self, x):
        if self.mask_flag == True and self.sparse_grads:
            weight = self.weight * self.weight_mask
            if self.bias_flag == True:
                bias = self.bias * self.bias_mask
            else:
                bias = self.bias
            return F.linear(x, weight, bias)
        else:
            return F.linear(x, self.weight, self.bias)


class MaskedConv2dDynamic(nn.Conv2d):
    def __init__(self, in_channels, out_channels, kernel_size, stride=1,
                 padding=0, dilation=1, groups=1, bias=True):
        super(MaskedConv2dDynamic, self).__init__(in_channels, out_channels,
                                           kernel_size, stride, padding, dilation, groups, bias)
        self.mask_flag = False
        self.bias_flag = bias

    def set_mask(self, weight_mask, bias_mask):
        self.weight_mask = to_var(weight_mask, requires_grad=False)
        self.weight.data = self.weight.data * self.weight_mask.data
        if self.bias_flag == True:
            self.bias_mask = to_var(bias_mask, requires_grad=False)
            self.bias.data = self.bias.data * self.bias_mask.data
        self.mask_flag = True

    def get_mask(self):
        return self.weight_mask, self.bias_mask

    def forward(self, x):
        if self.mask_flag == True:
            weight = self.weight * self.weight_mask
            if self.bias_flag == True:
                bias = self.bias * self.bias_mask
            else:
                bias = self.bias
            return F.conv2d(x, weight, bias, self.stride,
                            self.padding, self.dilation, self.groups)
        else:
            return F.conv2d(x, self.weight, self.bias, self.stride,
                            self.padding, self.dilation, self.groups)



#No Bias pruning
def random_prune(model, pruning_perc, skip_first = True):
    if pruning_perc > 0.0:
        model = copy.deepcopy(model)
        pruning_perc = pruning_perc / 100.0
        weight_masks = []
        bias_masks = []
    first_conv = skip_first
    for module in model.modules():
        if isinstance(module, nn.Linear):
            weight_mask = torch.from_numpy(np.random.choice([0, 1],
                                            module.weight.shape,
                                            p =  [pruning_perc, 1 - pruning_perc]))
            weight_masks.append(weight_mask)
            #do not prune biases
            bias_mask = torch.from_numpy(np.random.choice([0, 1],
                                            module.bias.shape,
                                            p =  [0, 1]))
            bias_masks.append(bias_mask)
        #Channel wise pruning Conv Layer
        elif isinstance(module, nn.Conv2d):
           if first_conv:
               connectivity_mask = torch.from_numpy(np.random.choice([0, 1],
                                                   (module.weight.shape[0],  module.weight.shape[1]),
                                                    p =  [0, 1]))
               first_conv = False
           else:
               connectivity_mask = torch.from_numpy(np.random.choice([0, 1],
                                                   (module.weight.shape[0],  module.weight.shape[1]),
                                                    p =  [pruning_perc, 1 - pruning_perc]))
           filter_masks = []
           for conv_filter in range(module.weight.shape[0]):

               filter_mask = []
               for inp_channel  in range(module.weight.shape[1]):
                   if connectivity_mask[conv_filter, inp_channel] == 1:
                       filter_mask.append(np.ones((module.weight.shape[2], module.weight.shape[3])))
                   else:
                       filter_mask.append(np.zeros((module.weight.shape[2], module.weight.shape[3])))
               filter_masks.append(filter_mask)

           weight_masks.append(torch.from_numpy(np.array(filter_masks)).to(torch.float32))

           #do not prune biases
           bias_mask = torch.from_numpy(np.random.choice([0, 1],
                                            module.bias.shape,
                                            p =  [0, 1])).to(torch.float32)
           bias_masks.append(bias_mask)
    model.set_masks(weight_masks, bias_masks)
    model.to(DEVICE)
    return model



class MLP(nn.Module):
    def __init__(self, input_dim, output_dim):
        super(MLP, self).__init__()
        self.penultimate_dim = 400
        self.layer1 = MaskedLinearDynamic(input_dim, 400)
        self.layer2 = MaskedLinearDynamic(400, 400)
        self.layer3 = MaskedLinearDynamic(400, 400)

        self.layer4 = MaskedLinearDynamic(400, output_dim)
        self.output_dim = output_dim
        self._initialize_weights()   

    def forward_activations(self, x, current_classes = None):

        #Forward pass as usual
        x = x.view(-1, 28 * 28)
        x1 = F.relu(self.layer1(x))
        x2 = F.relu(self.layer2(x1))
        x3 = F.relu(self.layer3(x2))
        x4 = self.layer4(x3)



        if current_classes is not None:
            mask = torch.zeros(self.output_dim)
            mask[current_classes] = 1
            x4 = x4 * mask.to(DEVICE)

        return x4, [x, x1, x2, x3, x4]



    def forward(self, x, current_classes = None):
        if x.shape[-1] == self.penultimate_dim:
            x = self.layer4(x)
        else:
            #Forward pass as usual
            x = x.view(-1, 28 * 28)
            x = F.relu(self.layer1(x))
            x = F.relu(self.layer2(x))
            x = F.relu(self.layer3(x))
            x = self.layer4(x)


        if current_classes is not None:
            mask = torch.zeros(self.output_dim)
            mask[current_classes] = 1
            x_masked = x * mask.to(DEVICE)
            return x_masked
        return x

    def re_initialize(self, freeze_masks):
        i = 0
        for m in self.modules():
            if isinstance(m, nn.Linear):
                if i == len(freeze_masks): break # Skip final layer for NISPA-Replay
                old_weights = m.weight.data.clone().detach()
                nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
                m.weight.data[torch.tensor(freeze_masks[i][0]).to(torch.bool)] = old_weights[torch.tensor(freeze_masks[i][0]).to(torch.bool)]

                old_bias = m.bias.clone().detach()
                nn.init.constant_(m.bias.data, 0)
                m.bias.data[torch.tensor(freeze_masks[i][1]).to(torch.bool)] =  old_bias[torch.tensor(freeze_masks[i][1]).to(torch.bool)]
                i += 1

    def _initialize_weights(self):
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
            elif isinstance(m, (nn.BatchNorm2d, nn.GroupNorm)):
                nn.init.constant_(m.weight, 1)
                nn.init.constant_(m.bias, 0)

    def set_masks(self, weight_mask,bias_mask):
       i = 0
       for module in self.modules():
           if isinstance(module, nn.Linear):
               module.set_mask(weight_mask[i],bias_mask[i])
               i = i + 1


def to_var(x, requires_grad = False, volatile = False):
    if isinstance(x, np.ndarray):
        x = torch.tensor(x)
    if torch.cuda.is_available():
        x = x.to(torch.device("cuda"))
    return Variable(x, requires_grad = requires_grad, volatile = volatile)


class ConvNet(nn.Module):
    def __init__(self, input_channels, output_dim, conv2lin_kernel_size = 64):
        super(ConvNet, self).__init__()
        self.penultimate_dim = 1024
        self.conv2lin_kernel_size = conv2lin_kernel_size
        self.conv1 = MaskedConv2dDynamic(in_channels=input_channels, out_channels=64, kernel_size=3, stride=1, padding=1, bias=True)
        self.conv2 = MaskedConv2dDynamic(in_channels=64, out_channels=64, kernel_size=3, stride=1, padding=1, bias=True)

        self.conv3 = MaskedConv2dDynamic(in_channels=64, out_channels=128, kernel_size=3, stride=1, padding=1, bias=True)
        self.conv4 = MaskedConv2dDynamic(in_channels=128, out_channels=128, kernel_size=3, stride=1, padding=1, bias=True)


        self.fc1 = MaskedLinearDynamic(128 * self.conv2lin_kernel_size, 1024)
        self.fc2 = MaskedLinearDynamic(1024, output_dim)
        self.output_dim = output_dim
        self._initialize_weights()

    def forward_activations(self, x, current_classes = None):
        x1 = F.relu(self.conv1(x))
        x2 = F.max_pool2d(F.relu(self.conv2(x1)), 2)

        x3 = F.relu(self.conv3(x2))
        x4 = F.max_pool2d(F.relu(self.conv4(x3)), 2)

        #Flatten
        x4_flat = x4.view(-1, 128 *  self.conv2lin_kernel_size)
        x5 = F.relu(self.fc1(x4_flat))
        x6 = self.fc2(x5)

        if current_classes is not None:
            mask = torch.zeros(self.output_dim)
            mask[current_classes] = 1
            x6 = x6 * mask.to(DEVICE)

        return x6, [x1, x2, x3, x4, x5, x6]


    def forward(self, x, current_classes = None):

        if x.shape[-1] == self.penultimate_dim:
            x = self.fc2(x)
        else:
            x = F.relu(self.conv1(x))
            x = F.max_pool2d(F.relu(self.conv2(x)), 2)

            x = F.relu(self.conv3(x))
            x = F.max_pool2d(F.relu(self.conv4(x)), 2)


            #Flatten
            x = x.view(-1, 128 *  self.conv2lin_kernel_size)
            x = F.relu(self.fc1(x))
            x = self.fc2(x)

        if current_classes is not None:
            mask = torch.zeros(self.output_dim)
            mask[current_classes] = 1
            x = x * mask.to(DEVICE)

        return x

    def re_initialize(self, freeze_masks):
        i = 0
        for m in self.modules():
            if isinstance(m, nn.Linear) or isinstance(m, nn.Conv2d):
                if i == len(freeze_masks): break # Skip final layer for NISPA-Replay
                old_weights = m.weight.data.clone().detach()
                nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
                m.weight.data[torch.tensor(freeze_masks[i][0]).to(torch.bool)] = old_weights[torch.tensor(freeze_masks[i][0]).to(torch.bool)]

                old_bias = m.bias.clone().detach()
                nn.init.constant_(m.bias.data, 0)
                m.bias.data[torch.tensor(freeze_masks[i][1]).to(torch.bool)] =  old_bias[torch.tensor(freeze_masks[i][1]).to(torch.bool)]
                i += 1

    def set_masks(self, weight_mask, bias_mask):
        i = 0
        for m in self.modules():
            if isinstance(m,(MaskedLinearDynamic, MaskedConv2dDynamic)):
                m.set_mask(weight_mask[i],bias_mask[i])
                i = i + 1


class Cycle:
    def __init__(self, loader):
        self.loader = loader
        self.generator = iter(loader)

    def get_batch(self):
        try:
            # Samples the batch
            return next(self.generator)
        except:
            # restart the generator if the previous generator is exhausted.
            self.generator = iter(self.loader)
            return next(self.generator)

#freeze_degree:  'full_freeze', "except_final", "slow_update" "no_freeze"
def reset_frozen_gradients(network, freeze_masks):
    mask_index = 0
    l = list(network.modules())[1:-1]

    for module in l:
        if isinstance(module, nn.Linear) or  isinstance(module, nn.Conv2d):
            module.weight.grad[freeze_masks[mask_index][0]] = 0
            module.bias.grad[freeze_masks[mask_index][1]] = 0
            mask_index += 1
    return network


def training_CL_memory(network, loss, optimizer, train_loader, memo_loader, test_loader,  args, epochs, freeze_masks = None):
    if memo_loader is not None:
        memo_loader_cycle = Cycle(memo_loader)  

    if freeze_masks is not None:
        freeze_masks = [(torch.tensor(w).to(torch.bool).to(DEVICE) , torch.tensor(b).to(torch.bool).to(DEVICE)) for w, b in freeze_masks]
    #Training
    train_curve = []
    accuracy1 = []
    test_loss = []

    for epoch in range(epochs):
        network.train()
        train_loss = 0
        for batch_idx, (data, target, _) in enumerate(train_loader):
            #print(torch.unique(target, return_counts=True))
            optimizer.zero_grad()
            output = network(data)

            if memo_loader is not None:
                data_memo, target_memo =  memo_loader_cycle.get_batch()
                output_memo = network(data_memo.to(DEVICE))
                l1 = loss(output, target.long())
                l2 = loss(output_memo, target_memo.to(DEVICE).long())
                batch_loss = l1  + args.replay_lambda *  l2
            else:
                batch_loss = loss(output, target.long())

            train_loss += batch_loss.item() * data.size(0)
            batch_loss.backward()
            if freeze_masks is not None:
                network = reset_frozen_gradients(network, freeze_masks)
            optimizer.step()

        train_curve.append(train_loss/len(train_loader.dataset))
        avg_loss, acc1, _ = test(network, loss, test_loader, current_classes = None, report=True)

        accuracy1.append(acc1)
        test_loss.append(avg_loss)


    return copy.deepcopy(network), train_curve, test_loss, accuracy1


def test(network, loss, dataloader,  title = "test", current_classes = None, report = False):
    network.eval()
    correct1 = 0
    correct5 = 0
    with torch.no_grad():
        for idx, (data, target, _) in enumerate(dataloader):
            output = network(data, current_classes)
            _, pred = output.topk(5, dim=1)
            correct = pred.eq(target.view(-1,1).expand_as(pred))
            correct1 += correct[:,:1].sum().item()
            correct5 += correct[:,:5].sum().item()

    acc1 = 100.0 * correct1 / len(dataloader.dataset)
    acc5 = 100.0 * correct5 / len(dataloader.dataset)

    if report:
        print('[{}] Top 1 Accuracy ='.format(title), acc1)

    return None, acc1, acc5

class Memory:
    def __init__(self, train_scenario, memo_size, nb_total_classes):
        self.memory = rehearsal.RehearsalMemory(
                memory_size=memo_size,
                herding_method="random",
                fixed_memory=0,
                nb_total_classes = nb_total_classes
            )
        self.train_scenario = copy.deepcopy(train_scenario)

    def push_penultimate(self, model, train_loader, task_id):
        model.train()
        all_activations = []
        targets = []
        task = []
        with torch.no_grad():
            for batch_idx, (data, target) in enumerate(train_loader):
                _, activations = model.forward_activations(data, None)
                all_activations.append(activations[-2])
                targets.append(target)
                task.append([task_id]* len(target))
        mem_x = np.concatenate([np.array(acti.cpu()) for acti in all_activations])
        mem_y = np.concatenate([np.array(l.cpu()) for l in targets])
        mem_t = np.concatenate([np.array(t) for t in task])
        self.memory.add(mem_x, mem_y, mem_t, z = False)

    def push_samples(self, task_id):
        #Get samples function applies transformation to samples
        #Use only normalization otherwise we will store augmented samples
        self.memory.add(*self.train_scenario[task_id].get_samples(range(len(self.train_scenario[task_id]))), z = False)


    def get_random_samples(self, n):
        l = len(self.memory)
        index = np.random.choice(list(range(l)), size = n, replace = False)
        mem_x, mem_y, mem_t = self.memory.get()
        return mem_x[index], mem_y[index], mem_t[index]

    #Use this to get pytorch dataset for memory samples
    def create_dataset(self):
        mem_x, mem_y, _ = self.memory.get()
        return  TensorDataset(torch.Tensor(mem_x),torch.Tensor(mem_y))


def randomly_set_zero_except_n(tensor, n):
    if n == 0:
        return np.zeros_like(tensor)
    if n > np.count_nonzero(tensor):
        return tensor

    new_tensor = np.zeros_like(tensor)
    non_zero_indices_dim0, non_zero_indices_dim1 = np.nonzero(tensor) if len(tensor.shape) == 2 else  np.nonzero(np.sum(tensor, axis = (2, 3)))
    if len(tensor.shape) == 4:
        n = int(n / (tensor.shape[2] * tensor.shape[3])) 
    indices_to_preserve = np.random.choice(range(len(non_zero_indices_dim0)), replace = False, size = n)
    non_zero_indices_dim0, non_zero_indices_dim1 = non_zero_indices_dim0[indices_to_preserve], non_zero_indices_dim1[indices_to_preserve]
    new_tensor[non_zero_indices_dim0, non_zero_indices_dim1]  = 1 if len(tensor.shape) == 2 else  np.ones((tensor.shape[2], tensor.shape[3]))

    return new_tensor




def progressive_rewiring(model, all_units, stable_indices, num_connections):
    pos_connections, bias_matrices = [], []

    #Get both type of connections
    pos_cons_SP, _ = forwardT_random(model, all_units, stable_indices)
    pos_cons_PP, _ = flow_random(model, all_units, stable_indices)

    PP_ratio = np.linspace(0.5, 1, len(num_connections))
    SP_ratio = np.linspace(1, 0.5, len(num_connections))

    for layer_index, (pos_con_SP, pos_con_PP) in enumerate(zip(pos_cons_SP, pos_cons_PP)):
       PP_con_num, SP_con_num =  math.ceil(num_connections[layer_index] * PP_ratio[layer_index]), math.floor(num_connections[layer_index] * SP_ratio[layer_index])
       pos_conn = randomly_set_zero_except_n(pos_cons_SP[layer_index], SP_con_num) + randomly_set_zero_except_n(pos_cons_PP[layer_index], PP_con_num)
       pos_connections.append(pos_conn)


       if len(pos_conn.shape) == 4:
           bias_matrix = copy.deepcopy(pos_conn.sum(axis = (2, 3)))
       else:
           bias_matrix = copy.deepcopy(pos_conn)

       bias_matrix[np.nonzero(bias_matrix)] =  bias_matrix[np.nonzero(bias_matrix)] / np.sum(bias_matrix)
       bias_matrices.append(bias_matrix)



    return pos_connections, bias_matrices


def connect_output2plastics(model, all_units, stable_indices, current_classes):
    #Get plastic units
    plastic_penultimate = set(list(range(all_units[-2]))).difference(stable_indices[-2])
    if len(plastic_penultimate) == 0:
        print("NO PLASTIC UNIT LEFT AT PENULTIMATE LAYER!!!!")
        print("GROWING CONNECTIONS FROM STABLE ONES")
        return model

    #Extract final layer
    final_layer = [i for i in model.modules()][-1]
    weight_mask, bias_mask = final_layer.get_mask()
    num_new_conns = torch.sum(weight_mask[current_classes, :])

    #Remove all previously assigned connections
    weight_mask[current_classes, :] = 0

    #Randomly select num_new_conns to create
    pos_conns = np.zeros((len(current_classes), len(plastic_penultimate)))
    try:
        indices = np.random.choice(pos_conns.shape[1]*pos_conns.shape[0], replace=False, size=int(num_new_conns))
        pos_conns[np.unravel_index(indices, pos_conns.shape)] = 1
    except:
        pos_conns = np.ones((len(current_classes), len(plastic_penultimate)))

    pos_conns = torch.tensor(pos_conns, dtype = weight_mask.dtype).to(DEVICE)

    #Grow connections
    for i, out_unit in enumerate(current_classes):
        weight_mask[int(out_unit), list(plastic_penultimate)] = pos_conns[i, :]

    final_layer.set_mask(weight_mask, bias_mask)

    return model    


