class Learner():
    def __init__(self, args, input_dim, output_dim, scenario_train, scenario_test, deterministic = True, train_tranform = None, test_transform = None): 
        self.args = args
        if args.optimizer == "adam":
            self.optim_obj = optim.Adam
        elif args.optimizer == "ada_delta":
            self.optim_obj= optim.Adadelta
        else:
            self.optim_obj= optim.SGD

        if deterministic:
            torch.manual_seed(args.seed)
            random.seed(args.seed)
            np.random.seed(args.seed)
            torch.use_deterministic_algorithms(True)
            torch.backends.cudnn.benchmark = False

        self.train_transform = train_tranform
        self.test_transform = test_transform

        self.Memo_train = Memory(scenario_train, args.memo_size, scenario_train.nb_classes)

        self.CIL = True
        self.input_dim = input_dim
        self.output_dim = output_dim
        if args.model == 'conv':
            self.model = ConvNet(input_dim, output_dim).to(DEVICE)
        else:
            self.model = MLP(input_dim, output_dim).to(DEVICE)
        print("Model: \n", self.model)

        self.scenario_train = scenario_train
        self.scenario_test = scenario_test
        self.pruned_model = random_prune(self.model, args.prune_perc)

        self.freeze_masks = None
        self.freeze_masks_old = None
        self.drop_masks = None
        self.stable_indices = None
        self.num_dropped_connections = 0
        self.classes_so_far = []
        self.stable_units_set = []

        if self.args.p_step_size == 'cosine':
            self.p_schedule = lambda t: cosine_anneling(t, self.args.step_size_param)
        elif self.args.p_step_size == 'exp_decay':
            self.p_schedule = lambda t: exp_decay(t, self.args.step_size_param)
        else: 
            self.p_schedule = lambda t: linear(t, self.args.step_size_param)

    #task_id should start from 0
    #taskset is object of continuum library 
    def task_train(self, task_id, taskset, val_set = None):
        current_classes = list(taskset.get_classes())
        self.classes_so_far += current_classes
        print("Task ID: ", task_id + 1, " Classes: ", current_classes)
        #Create data loaders
        if val_set is None:
            train_taskset, val_taskset = split_train_val(taskset, val_split=0.1)
            val_loader = DataLoader(val_taskset,  batch_size= self.args.batch_size,  shuffle=True, collate_fn=lambda x: tuple(x_.to(DEVICE) for x_ in default_collate(x)))
        else:
            train_taskset = taskset
            val_loader = DataLoader(val_set,  batch_size= self.args.batch_size,  shuffle=True, collate_fn=lambda x: tuple(x_.to(DEVICE) for x_ in default_collate(x)))


        train_loader = DataLoader(train_taskset,  batch_size= self.args.batch_size,  shuffle=True, collate_fn=lambda x: tuple(x_.to(DEVICE) for x_ in default_collate(x)))

        #Get training objects
        loss = nn.CrossEntropyLoss()

        #Iterative FineTuning Step
        previous_model = None
        current_model = self.pruned_model
        stable_units_set =  self.stable_units_set
        stable_indices = self.stable_indices
        stable_indices_prev = None
        p_prev = 100
        p_new = 100
        acc_prev = 0
        connectivity_before = copy.deepcopy(get_masks(self.pruned_model))
        print('Starting:')
        t = 0
        list_of_ps = []
        num_stable_units = []

        while(True):
            t = t + 1
            stable_perc = self.p_schedule(t) * 100

            print('Model sparsity before training:', compute_weight_sparsity(current_model))

            #Reset optimizer for every task
            optimizer = self.optim_obj(current_model.parameters(), lr= self.args.learning_rate, weight_decay= 0)
            connectivity_before = copy.deepcopy(get_masks(current_model))

            try:
                memo_loader = DataLoader(self.Memo_train.create_dataset(), batch_size = self.args.batch_size, shuffle=True,
                collate_fn=lambda x: tuple(x_.to(DEVICE) for x_ in default_collate(x)))
            except:
                memo_loader = None
            current_model, _, _, acc_after_fine_tuning = training_CL_memory(
                current_model, loss, optimizer, train_loader,
                memo_loader, val_loader, self.args, 
                self.args.phase_epochs, freeze_masks = self.freeze_masks)

            acc_new = acc_after_fine_tuning[-1]
            #Accuracy Dropped stop iteration
            if (acc_new < (acc_prev - self.args.recovery_perc) and t > self.args.min_phases) or stable_perc <= 5:
                self.pruned_model = previous_model
                if len(self.stable_units_set) == 0:
                    self.stable_units_set = [set(stable_index) for stable_index in stable_indices_prev]
                    self.stable_indices =  [list(stable_set) for stable_set in self.stable_units_set]
                else:
                    self.stable_units_set = [prev_set.union(set(stable_index)) for stable_index, prev_set in zip(stable_indices_prev, self.stable_units_set)]
                    self.stable_indices =  [list(stable_set) for stable_set in self.stable_units_set]
                self.freeze_masks, _ = compute_freeze_and_drop(self.stable_indices, self.pruned_model)
                if  self.args.reinit:
                    self.pruned_model.re_initialize(self.freeze_masks)
                break
            else:
                acc_prev = max(acc_new, acc_prev)
                previous_model = current_model
                stable_indices_prev = stable_indices
                p_prev = p_new
                num_stable_units.append(stable_indices_prev)
                list_of_ps.append(p_prev)

            print('Dropping for p:{}:'.format(stable_perc))
            current_model, _, num_dropped_connections, stable_indices, stable_units_set = compute_stable_and_drop_connections(
                                                                               current_model,  self.input_dim, self.stable_units_set, 
                                                                               train_loader, current_classes, 
                                                                               self.classes_so_far, stable_perc,  model_type= self.args.model )

            if  self.args.grow:
                #Grow connections
                connectivity_after = copy.deepcopy(get_masks(current_model))
                num_dropped_connections =  [torch.sum(torch.abs(a  - b)).cpu().numpy() for a, b in zip(connectivity_before, connectivity_after)]
                plastic_units = compute_plastic(current_model, stable_indices)
                #Fix Non importants without outgoing connections
                current_model, remainder_connections = fix_no_outgoing(current_model, plastic_units, num_dropped_connections)
                weights = list_of_weights(current_model)


                activations, _ = compute_average_activation(current_model, train_loader, DEVICE, current_classes, False)
                current_model, remainder_connections = grow_connection_A2B(current_model, remainder_connections,
                                                       [weights[0][0].shape[1]]  + [w.shape[0] for w, _ in weights], 
                                                       stable_indices,  activations, 
                                                       grow_algo = self.args.rewire_algo, 
                                                       weight_init_algo = self.args.grow_init)

                #Alternative growth
                current_model, remainder_connections = grow_connection_A2B(current_model, remainder_connections,
                                                       [weights[0][0].shape[1]]  + [w.shape[0] for w, _ in weights], 
                                                       stable_indices,  activations, 
                                                       grow_algo = 'full_random', 
                                                       weight_init_algo = self.args.grow_init)

            p_new = stable_perc
        print('End:')

        self.Memo_train.push_samples(task_id)

        percentange_of_frozen_conns = connection_freeze_perc(self.freeze_masks, self.args.prune_perc)

        backward_accs, backward_tasks, cum_acc = task_summary_log(self.pruned_model, loss,
                                current_classes, self.args, 
                                task_id, self.scenario_test, self.stable_units_set)




        return p_prev, percentange_of_frozen_conns, backward_accs[0], 0, list_of_ps[1:], num_stable_units[1:]

def parse_block_mapping_for_stage(string):    mapping = dict()    mapping_strs = string.split(';')    try:        for s in mapping_strs:            src_id_str, tgt_ids_str = s.split(':')            src_id = int(src_id_str)            tgt_ids = [int(t) for t in tgt_ids_str.split(',')]
            mapping[src_id] = tgt_ids        return mapping    except:        raise RuntimeError('Invalid block mapping string.')
def change_depth(model_name, src_sd, dst_sd, mappings, seed=None, permute_copy=False):
    if 'resnet' in model_name and 'cifar' in model_name:
        return change_depth_cifar_resnet(src_sd, dst_sd, mappings, seed=seed, permute_copy=permute_copy)
    elif 'vgg' in model_name and 'cifar' in model_name:
        return change_depth_cifar_vgg(src_sd, dst_sd, mappings)
    elif 'lenet' in model_name and 'mnist' in model_name:
        return change_depth_mnist_lenet(src_sd, dst_sd, mappings)
    else:
        raise NotImplementedError(f'Depth morphism method is not implemeted yet for {model_name}')
def change_depth_cifar_vgg(src_sd, dst_sd, mappings):
    dst_sd = copy.deepcopy(dst_sd)
    src_layer_ids = set()
    for k in src_sd.keys():
        if 'layers' in k:
            src_layer_ids.add(int(k.split('.')[1]))
    src_max_layer_id = max(src_layer_ids)
    dst_layer_ids = set()
    for k in dst_sd.keys():
        if 'layers' in k:
            dst_layer_ids.add(int(k.split('.')[1]))
    dst_max_layer_id = max(dst_layer_ids)
    src_stage_mapping = {i:[] for i in range(5)}
    cur_stage_id = 0
    for i in range(src_max_layer_id + 1):
        if f'layers.{i}.conv.weight' in src_sd:
            src_stage_mapping[cur_stage_id].append(i)
        else:
            cur_stage_id += 1
    dst_stage_mapping = {i:[] for i in range(5)}
    cur_stage_id = 0
    for i in range(dst_max_layer_id + 1):
        if f'layers.{i}.conv.weight' in dst_sd:
            dst_stage_mapping[cur_stage_id].append(i)
        else:
            cur_stage_id += 1
    def get_stage_local_id(stage_mapping, layer_id):
        for stage_id, stage_layer_ids in stage_mapping.items():
            if layer_id in stage_layer_ids:
                return stage_id, layer_id - stage_layer_ids[0]
    def get_layer_id(stage_mapping, stage_id, local_id):
        return stage_mapping[stage_id][0] + local_id
    overwritten_keys = []
    for k,v in src_sd.items():
        if 'layers' not in k: 
            dst_sd[k] = v.clone()
            overwritten_keys.append(k)
            continue
        split_k = k.split('.')
        src_layer_id = int(split_k[1])
        stage_id, src_local_id = get_stage_local_id(src_stage_mapping, src_layer_id)
        dst_local_id_list = mappings[stage_id].get(src_local_id, [])
        for dst_local_id in dst_local_id_list:
            dst_layer_id = get_layer_id(dst_stage_mapping, stage_id, dst_local_id)
            new_split_k = copy.deepcopy(split_k)
            new_split_k[1] = str(dst_layer_id)
            dst_k = '.'.join(new_split_k)
            dst_sd[dst_k] = v.clone()
            overwritten_keys.append(dst_k)
    all_overwritten = True
    for k in dst_sd.keys():
        all_overwritten = all_overwritten and k in overwritten_keys
    assert overwritten_keys
    return dst_sd
def change_depth_cifar_resnet(src_sd, dst_sd, mappings, seed=None, permute_copy=False):
    dst_sd = copy.deepcopy(dst_sd)
    src_milestones = set([0])
    dst_milestones = set([0])
    for k in src_sd.keys():
        if 'blocks' in k and 'shortcut' in k:
            src_milestones.add(int(k.split('.')[1]))
    for k in dst_sd.keys():
        if 'blocks' in k and 'shortcut' in k:
            dst_milestones.add(int(k.split('.')[1]))
    src_milestones = sorted(src_milestones)
    dst_milestones = sorted(dst_milestones)
    src_stage_len = src_milestones[1]
    dst_stage_len = dst_milestones[1]
    overwritten_keys = []
    permute_counter = 0
    for k,v in src_sd.items():
        if 'blocks' in k:
            splitted_key = k.split('.')
            src_block_id = int(splitted_key[1])
            for i in range(len(src_milestones)-1, -1, -1):
                if src_block_id >= src_milestones[i]:
                    stage_id = i
                    break
            src_local_id = src_block_id - src_milestones[stage_id]
            dst_local_id_list = mappings.get(src_local_id, [])
            for j, dst_local_id in enumerate(dst_local_id_list):
                dst_block_id = stage_id * dst_stage_len + dst_local_id
                dst_key = copy.deepcopy(splitted_key)
                dst_key[1] = str(dst_block_id)
                dst_key = '.'.join(dst_key)
                assert dst_key in dst_sd
                if j > 0 and permute_copy:
                    dst_sd[dst_key] = shuffle_tensor(v.clone(), seed=seed + permute_counter)
                    permute_counter += 1
                else:
                    dst_sd[dst_key] = v.clone()
                overwritten_keys.append(dst_key)
        else:
            assert k in dst_sd
            dst_sd[k] = v
            overwritten_keys.append(k)
    all_overwritten = True
    for k in dst_sd.keys():
        all_overwritten = all_overwritten and k in overwritten_keys
    assert all_overwritten
    return dst_sd

class ChangeDepthBranch(base.Branch):
    def branch_function(
        self,
        target_model_name: str = None,
        block_mapping: str = None,
        start_at_step_zero: bool = False
    ):
        if 'cifar' in target_model_name and 'resnet' in target_model_name:
            mappings = parse_block_mapping_for_stage(block_mapping)
        elif 'mnist' in target_model_name and 'lenet' in target_model_name:
            mappings = parse_block_mapping_for_stage(block_mapping)
        elif 'cifar' in target_model_name and 'vgg' in target_model_name:
            mappings = list(map(parse_block_mapping_for_stage, block_mapping.split('|')))
        else:
            raise NotImplementedError('Other mapping cases not implemented yet')
        src_mask = Mask.load(self.level_root)
        start_step = self.lottery_desc.str_to_step('0it') if start_at_step_zero else self.lottery_desc.train_start_step
        src_model = models.registry.load(self.level_root, start_step, self.lottery_desc.model_hparams)
        target_model_hparams = copy.deepcopy(self.lottery_desc.model_hparams)
        target_model_hparams.model_name = target_model_name
        target_model = models.registry.get(target_model_hparams)
        target_ones_mask = Mask.ones_like(target_model)
        target_sd = change_depth(target_model_name, src_model.state_dict(), target_model.state_dict(), mappings)
        target_model.load_state_dict(target_sd)
        target_mask = change_depth(target_model_name, src_mask, target_ones_mask, mappings)
        target_model = PrunedModel(target_model, target_mask)
        target_mask.save(self.branch_root)
        train.standard_train(target_model, self.branch_root, self.lottery_desc.dataset_hparams,
                             self.lottery_desc.training_hparams, start_step=start_step, verbose=self.verbose)
    @staticmethod
    def description():
        return "Change the depth of the source network."
    @staticmethod
    def name():
        return 'change_depth'

