def filt_param_to_merge(pt_weight, ft_weights):
    names = []
    for n in pt_weight['model']:
        flag = True
        for ft_weight in ft_weights:
            if n not in ft_weight['model'] or  pt_weight['model'][n].shape != ft_weight['model'][n].shape:
                flag = False
                break
        if flag:
            names.append(n)
    return names

def Task_Vectors(pt_weight, ft_weights):
    param_names_to_merge = filt_param_to_merge(pt_weight, ft_weights)
    vectors = []
    for ft_weight in ft_weights:
        vector = {}
        for n in param_names_to_merge:
            vector[n] = ft_weight['model'][n] - pt_weight['model'][n]
        vectors.append(vector)
    return vectors

def EMR_merge(task_vectors):
    sum_param = {}
    n2p = []
    for m in range(len(task_vectors)):
        n2p_temp = task_vectors[m]
        n2p.append(n2p_temp)
        for n in n2p_temp:
            if n not in sum_param:
                sum_param[n] = []
            sum_param[n].append(n2p_temp[n])
    sum_param = {k: torch.stack(v, 0).mean(0) for k, v in sum_param.items()}
    Vector_unified = {}
    scales = torch.zeros(len(task_vectors))
    masks = {}
    for n in sum_param:
        masks[n] = []
        flag = (sum_param[n]>0)*2-1
        param_max = torch.zeros_like(n2p[0][n])
        for m in range(len(task_vectors)):
            param = task_vectors[m][n]
            mask = (param * flag)>0
            masks[n].append(mask)
            param_abs = torch.abs(mask*param)
            param_max = torch.where(param_abs>param_max, param_abs, param_max)
            scales[m] += torch.mean(torch.abs(param))
            pass
        Vector_unified[n] =  param_max * flag

    new_scales = torch.zeros(len(task_vectors))
    for m in range(len(task_vectors)):
        for n in Vector_unified:
            p = Vector_unified[n] * masks[n][m]
            new_scales[m] += torch.mean(torch.abs(p))
    rescales = scales / new_scales

    return Vector_unified, masks, rescales

def main():
    ckpt_path = './model_weights/'
    ft_ckpt_name = ['beit3_base_patch16_480_vqav2.pth', 'beit3_base_patch16_480_coco_captioning.pth', 'beit3_base_patch16_384_coco_retrieval.pth', 'beit3_base_patch16_224_nlvr2.pth', 'beit3_base_patch16_224_in1k.pth']
    tasks = ['vqav2', 'coco_captioning', 'coco_retrieval', 'nlvr2', 'imagenet']
    ft_model_weights = []
    for ckpt in ft_ckpt_name:
        ft_model_weights.append(torch.load(ckpt_path+ckpt))
    pt_model_name = "beit3_base_patch16_224.pth"
    pt_model_weight = torch.load(ckpt_path + pt_model_name)
    vectors = Task_Vectors(pt_model_weight, ft_model_weights)
    Vector_unified, masks, rescales = EMR_merge(vectors)
    param_recon = {}
    opts, ds_init = get_args()
    if opts.output_dir:
        Path(opts.output_dir).mkdir(parents=True, exist_ok=True)
    try:
        task_num = tasks.index(opts.task)
    except:
        raise ValueError('Task not applicable!!!')
    for n in Vector_unified:
        param_recon[n] = Vector_unified[n] * masks[n][task_num] * rescales[task_num] + pt_model_weight['model'][n]
    ft_model = ft_model_weights[task_num]
    for n in param_recon:
        ft_model['model'][n] = param_recon[n]
    val(ft_model, ds_init, opts)

if __name__ == '__main__':
    main()

class ResidualAttentionBlock(nn.Module):    def __init__(self, d_model: int, n_head: int, attn_mask: torch.Tensor = None):        super().__init__()        self.attn = nn.MultiheadAttention(d_model, n_head)        self.ln_1 = LayerNorm(d_model)        self.mlp = nn.Sequential(OrderedDict([            ("c_fc", nn.Linear(d_model, d_model * 4)),            ("gelu", QuickGELU()),            ("c_proj", nn.Linear(d_model * 4, d_model))        ]))        self.ln_2 = LayerNorm(d_model)        self.attn_mask = attn_mask    def attention(self, x: torch.Tensor):        self.attn_mask = self.attn_mask.to(dtype=x.dtype, device=x.device) if self.attn_mask is not None else None        return self.attn(x, x, x, need_weights=False, attn_mask=self.attn_mask)[0]    def forward(self, x: torch.Tensor):        x = x + self.attention(self.ln_1(x))        x = x + self.mlp(self.ln_2(x))        return x

def zerolike_params_dict(model, device=None):
    """
    Create a list of (name, parameter), where parameter is initalized to zero.
    The list has as many parameters as model, with the same size.

    :param model: a pytorch model
    """

    return [
        (k, torch.zeros_like(p).to(p.device if (device == None) else device))
        for k, p in model.named_parameters()
    ]


def copy_params_dict(model, copy_grad=False, device=None):
    """
    Create a list of (name, parameter), where parameter is copied from model.
    The list has as many parameters as model, with the same size.

    :param model: a pytorch model
    :param copy_grad: if True returns gradients instead of parameter values
    """

    if copy_grad:
        return [(k, p.grad.data.detach().clone()) for k, p in model.named_parameters()]
    else:
        return [(k, p.data.detach().clone().to(p.device if (device == None) else device)) for k, p in
                model.named_parameters()]


class SPU(Finetune):
    def __init__(self, args):
        super().__init__(args)
        self.mask = {}
        self.trainable_params = []


    def compute_score(self, model, dataloader, **kwargs):


        # Initialize importance matrix
        importance = dict(zerolike_params_dict(model, device=self.args.device))

        # Do forward and backward pass to accumulate L2-loss gradients
        model.train()
        model.zero_grad()
        total_batch =  len(dataloader)
        num_batch_for_score = total_batch * self.args.score_batch_percentage
        print(f'Total batch for importance {total_batch}, use {num_batch_for_score} batches')
        stop_flag = 1


        for num_batch, batch in enumerate(tqdm(dataloader)):
            stop_flag = 1
            # Get batch
            images, _, texts = batch
            images = images.to(self.args.device)
            texts = texts.to(self.args.device)

            # Forward pass
            logits_per_image, logits_per_text = model(images, texts)

            # Average L2-Norm of the output
            loss = torch.norm(logits_per_image, p="fro", dim=1).pow(2).mean()
            loss.backward()

            # Accumulate importance
            for name, param in model.named_parameters():
                if param.requires_grad:
                    if param.grad is not None:
                        importance[name].data += param.grad.clone()
                        if importance[name].data.abs().min() < 1e-12:
                            stop_flag = 0
            if num_batch > num_batch_for_score and stop_flag:
                break

        return importance


    def compute_importance(self, dataset, model, task):


        cur_set = dataset.get_dataset(task, is_train=True, with_buffer=False)
        loader = self.get_loader(cur_set, is_train=True)
        print('Compute importance for the current task...')
        cur_importance = self.compute_score(model, loader, task=task,dataset=dataset)
        if self.args.save_ckpt:
            with open(os.path.join(self.args.log_path, f'task{task}_importance.torchSave'), 'wb') as file:
                torch.save(cur_importance, file)

        with torch.no_grad():
            for name, param in model.named_parameters():
                if name in self.trainable_params:
                    if any(param in name for param in self.args.full_update_param) or self.args.selection_rate == 1.0:
                        self.mask[name] = torch.ones(param.shape, dtype=param.dtype).to(self.args.device)
                        continue
                    if name not in cur_importance.keys():
                        print(f' importance of `{name} is none')
                        continue
                    importance = cur_importance[name]
                    magnitudes = importance.abs()
                    k = int(magnitudes.numel() * self.args.selection_rate)

                    topk_values, topk_indices = torch.topk(magnitudes.view(-1), k=k)
                    self.mask[name] = torch.zeros_like(magnitudes).to(self.args.device)
                    self.mask[name].view(-1)[topk_indices] = 1

    def unfreeze_model(self, model):
        model.train()
        for name, param in model.named_parameters():
            if name == 'visual.proj':
                if self.args.finetune_proj:
                    trainable_params = True
                else:
                    trainable_params = False
            else:
                trainable_params = self.args.edit_layer in name

            if trainable_params:
                param.requires_grad = True
                if name not in self.trainable_params:
                    self.trainable_params.append(name)
            else:
                param.requires_grad = False
        print('Trainable parameters: ', self.trainable_params)

    def update_model(self, model, optimizer, **kwargs):
        with torch.no_grad():
            for name, param in model.named_parameters():
                gradients = param.grad
                if gradients is not None:
                    param.grad = self.mask[name] * param.grad
        optimizer.step()


class Buffer:
    """
    The memory buffer of rehearsal method.
    """

    def __init__(self, buffer_size, device, n_tasks=None, mode='reservoir'):
        assert mode in ['ring', 'reservoir']
        self.buffer_size = buffer_size
        self.device = torch.device(device)
        self.num_seen_examples = 0
        self.functional_index = eval(mode)
        if mode == 'ring':
            assert n_tasks is not None
            self.task_number = n_tasks
            self.buffer_portion_size = buffer_size // n_tasks
        self.attributes = ['examples', 'labels', 'logits', 'task_labels']

    def init_tensors(self, examples: torch.Tensor, labels: torch.Tensor,
                     logits: torch.Tensor, task_labels: torch.Tensor) -> None:
        """
        Initializes just the required tensors.
        :param examples: tensor containing the images
        :param labels: tensor containing the labels
        :param logits: tensor containing the outputs of the network
        :param task_labels: tensor containing the task labels
        """
        for attr_str in self.attributes:
            attr = eval(attr_str)
            if attr is not None and not hasattr(self, attr_str):
                typ = torch.int64 if attr_str.endswith('els') else torch.float32

                setattr(self, attr_str, torch.zeros((self.buffer_size,
                        *attr.shape[1:]), dtype=typ, device=self.device))

    def add_data(self, examples, labels=None, logits=None, task_labels=None):
        """
        Adds the data to the memory buffer according to the reservoir strategy.
        :param examples: tensor containing the images
        :param labels: tensor containing the labels
        :param logits: tensor containing the outputs of the network
        :param task_labels: tensor containing the task labels
        :return:
        """
        if not hasattr(self, 'examples'):
            self.init_tensors(examples, labels, logits, task_labels)

        for i in range(examples.shape[0]):
            index = reservoir(self.num_seen_examples, self.buffer_size)
            self.num_seen_examples += 1
            if index >= 0:
                self.examples[index] = examples[i].to(self.device)
                if labels is not None:
                    self.labels[index] = labels[i].to(self.device)
                if logits is not None:
                    self.logits[index] = logits[i].to(self.device)
                if task_labels is not None:
                    self.task_labels[index] = task_labels[i].to(self.device)

    def get_data(self, size: int, transform: transforms = None) -> Tuple:
        """
        Random samples a batch of size items.
        :param size: the number of requested items
        :param transform: the transformation to be applied (data augmentation)
        :return:
        """
        if size > min(self.num_seen_examples, self.examples.shape[0]):
            size = min(self.num_seen_examples, self.examples.shape[0])

        choice = np.random.choice(min(self.num_seen_examples, self.examples.shape[0]),
                                  size=size, replace=False)
        if transform is None:
            def transform(x): return x
        ret_tuple = (torch.stack([transform(ee.cpu())
                                  for ee in self.examples[choice]]).to(self.device),)
        for attr_str in self.attributes[1:]:
            if hasattr(self, attr_str):
                attr = getattr(self, attr_str)
                ret_tuple += (attr[choice],)

        return ret_tuple

    def is_empty(self) -> bool:
        """
        Returns true if the buffer is empty, false otherwise.
        """
        if self.num_seen_examples == 0:
            return True
        else:
            return False

    def get_all_data(self, transform: transforms = None) -> Tuple:
        """
        Return all the items in the memory buffer.
        :param transform: the transformation to be applied (data augmentation)
        :return: a tuple with all the items in the memory buffer
        """
        if transform is None:
            def transform(x): return x
        ret_tuple = (torch.stack([transform(ee.cpu())
                                  for ee in self.examples]).to(self.device),)
        for attr_str in self.attributes[1:]:
            if hasattr(self, attr_str):
                attr = getattr(self, attr_str)
                ret_tuple += (attr,)
        return ret_tuple

    def empty(self) -> None:
        """
        Set all the tensors to None.
        """
        for attr_str in self.attributes:
            if hasattr(self, attr_str):
                delattr(self, attr_str)
        self.num_seen_examples = 0
